<template><router-link :to="`/play/${item.id}`" class="video-card"><div class="thumb"><img :src="cover" :alt="item.title" loading="lazy" decoding="async" @error="failed=true"><span class="badge">{{item.updateTime||''}}</span><span class="duration">{{item.duration||'HD'}}</span><div class="thumb-meta"><span>◉ {{formatViews(item.views)}}</span><span>{{item.year||''}}</span></div><span class="play-hover">▶</span></div><h3>{{item.title}}</h3><div class="stats"><span>◉ {{formatViews(item.views)}}</span><span v-if="item.score" class="score">★ {{item.score}}</span></div></router-link></template><script setup>import{computed,ref}from'vue';const props=defineProps({item:{type:Object,required:true}}),failed=ref(false),fallback='/fallback.svg',cover=computed(()=>failed.value?fallback:props.item?.poster||fallback);function formatViews(v){const n=Number(v)||0;return n>999999?`${(n/1000000).toFixed(1)}M`:n>999?`${(n/1000).toFixed(1)}K`:String(n)}</script>